 FrameworkElement DesignSlider(string key,string title){var panel=new Grid{Margin=new Thickness(0,4,0,6)};panel.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(105)});panel.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});panel.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(66)});var label=MT(title,12);label.VerticalAlignment=VerticalAlignment.Center;panel.Children.Add(label);var slider=Detach(montageSliders[key]);slider.VerticalAlignment=VerticalAlignment.Center;slider.Margin=new Thickness(0,0,7,0);Grid.SetColumn(slider,1);panel.Children.Add(slider);var number=new TextBox{Padding=new Thickness(5,3,5,3),VerticalContentAlignment=VerticalAlignment.Center,FontSize=12,MinWidth=55};number.SetBinding(TextBox.TextProperty,new Binding("Value"){Source=slider,Mode=BindingMode.TwoWay,UpdateSourceTrigger=UpdateSourceTrigger.LostFocus,StringFormat="0.##",ValidatesOnExceptions=true});Grid.SetColumn(number,2);panel.Children.Add(number);return panel;}
 FrameworkElement DesignPosition(){var panel=new Grid{Margin=new Thickness(0,3,0,3)};panel.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(105)});panel.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});panel.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});panel.Children.Add(MT("Позиция",12));int col=1;foreach(string key in new[]{"X","Y"}){var slider=Detach(montageSliders[key]);var box=new TextBox{Padding=new Thickness(6,3,6,3),Margin=new Thickness(2,0,2,0),FontSize=12,Height=27};box.SetBinding(TextBox.TextProperty,new Binding("Value"){Source=slider,Mode=BindingMode.TwoWay,UpdateSourceTrigger=UpdateSourceTrigger.LostFocus,StringFormat="0.##",ValidatesOnExceptions=true});Grid.SetColumn(box,col++);panel.Children.Add(box);}return panel;}
 FrameworkElement DesignRow(string title,FrameworkElement control){var grid=new Grid{Margin=new Thickness(0,1,0,1)};grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(155)});grid.Children.Add(MT(title,12));Grid.SetColumn(control,1);grid.Children.Add(control);return grid;}
 FrameworkElement DesignField(string title,TextBox field){var row=new DockPanel{Margin=new Thickness(0,4,0,4)};Detach(field);field.Width=112;field.Height=29;field.Padding=new Thickness(8,4,8,4);DockPanel.SetDock(field,Dock.Right);row.Children.Add(field);row.Children.Add(MT(title));return row;}
 Expander DesignAccordion(string title,UIElement child,bool open){return new Expander{Header=title,Content=new Border{Child=child,Padding=new Thickness(12,5,12,10)},IsExpanded=open,Margin=new Thickness(0,4,0,5),Background=Gradient("#211b30","#14111f"),BorderBrush=MC("#39304b"),BorderThickness=new Thickness(1)};}
 void AddInspectorSection(string name,UIElement content){var holder=new Border{Child=content,Visibility=Visibility.Collapsed};designSections[name]=holder;inspectorContent.Children.Add(holder);}
 void SelectInspector(string name){if(designInspector!=null){var tabs=designInspector.Children[0] as StackPanel;if(tabs!=null)foreach(Button tab in tabs.Children.OfType<Button>()){bool active=Convert.ToString(tab.Content)==name;tab.Background=active?(Brush)Gradient("#65328b","#3c2055"):MC("#11101b");tab.BorderBrush=MC(active?"#ab61df":"#39304d");}}foreach(var p in designSections)p.Value.Visibility=p.Key==name?Visibility.Visible:Visibility.Collapsed;}
 void UpdateDesignStats(){if(designLibraryTitle==null)return;int dw,dh;Dimensions(new EditSettings{Aspect=montage.Aspect,Resolution=montage.Resolution},false,out dw,out dh);if(designPreviewTitle!=null)designPreviewTitle.Text="Предпросмотр "+(montage.Aspect==0?"9:16":montage.Aspect==1?"1:1":"16:9")+" ("+dw+"×"+dh+")";if(designEmptyRecent!=null)designEmptyRecent.Visibility=montage.Assets.Count==0?Visibility.Visible:Visibility.Collapsed;designLibraryTitle.Text="Материалы ("+montage.Assets.Count+")";if(recentMedia!=null){recentMedia.ItemsSource=null;recentMedia.ItemsSource=montage.Assets;}if(designStats!=null)designStats.Text="Проект: "+(montage.Items.Count==0?"Новый":"Монтаж")+"    │    Длительность: "+Time(montage.Duration)+"    │    Видео: "+montage.Tracks.Count(t=>t.Kind=="video")+"    Аудио: "+montage.Tracks.Count(t=>t.Kind=="audio")+"    Текст: "+montage.Tracks.Count(t=>t.Kind=="text");}
}
